import { existsSync, readFileSync } from 'node:fs';

// Read the known audit file — the second test-assertion channel alongside the UI. The app appends
// one record per line; specs filter it by their sheet id. Path comes from AUDIT_FILE (set by
// bin/start / bin/e2e); falls back to the app's default.
const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';

/** All audit records currently in the file, one per element (empty if none). */
export function auditLines(): string[] {
  return existsSync(AUDIT_FILE)
    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
    : [];
}

// Usage in a spec (audit-category test):
//   expect(auditLines()).toContain('OWNER_CREATED id=1 name=Acme');
import { useQuery } from '@tanstack/react-query';
import { listPeople, peopleKey } from '../people/api';
import { claimsKey, listClaims, liveClaims, sumAmounts } from './api';

/** The sheet's claimed-total: everyone's OPEN and SETTLED claims added up (but the OPEN claims dated
 *  within a hold of their person, unless a statement bound them). */
export function ClaimedTotal({ sheetId }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  return (
    <p>
      Claimed total <span data-testid="rollup-claimed-total">{sumAmounts(liveClaims(claims.data ?? [], people.data))}</span>
    </p>
  );
}
